package com.dexm.personajes.adapter.out.persistence;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="characters") public class CharacterEntity {
 @Id private String id; private String name; private String campaignId; @Column(name="owner_user_id") private String ownerUserId; @Column(name="image_url", columnDefinition="longtext") private String imageUrl; private int experience; private int level; private int evolutionPoints; private int geneticsPoints; @Column(name="unique_ability_decisions_json", columnDefinition="text", nullable=false) private String uniqueAbilityDecisionsJson = "{}"; @Column(nullable=false) private boolean closed; @Column(name="attributes_json", columnDefinition="text") private String attributesJson; @Column(name="genetics_json", columnDefinition="text") private String geneticsJson; @Column(name="creation_mode", nullable=false) private String creationMode = "empty"; private String race; @Column(nullable=false) private boolean einherjer = true; @Column(nullable=false) private boolean awakened; @Column(name="einherjer_origin") private String einherjerOrigin; @Column(name="starting_age") private Integer startingAge; @Column(name="awakening_age") private Integer awakeningAge; @Column(name="sheet_age") private Integer sheetAge; @Column(name="selected_major_attributes_json", columnDefinition="text", nullable=false) private String selectedMajorAttributesJson = "[]"; @Column(name="creation_wizard_state", nullable=false) private String creationWizardState = "empty"; private Instant createdAt; private Instant updatedAt;
 protected CharacterEntity(){} public CharacterEntity(String id,String name,int experience,String attributesJson,String geneticsJson){this(id,null,name,null,experience,1,attributesJson,geneticsJson);} public CharacterEntity(String id,String campaignId,String name,String imageUrl,int experience,String attributesJson,String geneticsJson){this(id,campaignId,name,imageUrl,experience,1,attributesJson,geneticsJson);} public CharacterEntity(String id,String campaignId,String name,String imageUrl,int experience,int level,String attributesJson,String geneticsJson){this.id=id;this.campaignId=campaignId;this.name=name;this.imageUrl=imageUrl;this.experience=experience;this.level=level;this.attributesJson=attributesJson;this.geneticsJson=geneticsJson;this.createdAt=Instant.now();this.updatedAt=this.createdAt;}
 public String getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getCampaignId(){return campaignId;} public String getOwnerUserId(){return ownerUserId;} public void setOwnerUserId(String v){ownerUserId=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public int getExperience(){return experience;} public void setExperience(int v){experience=v;} public int getLevel(){return level;} public void setLevel(int v){level=Math.max(1,v);} public int getEvolutionPoints(){return evolutionPoints;} public void setEvolutionPoints(int v){evolutionPoints=Math.max(0,v);} public int getGeneticsPoints(){return geneticsPoints;} public void setGeneticsPoints(int v){geneticsPoints=Math.max(0,v);} public String getUniqueAbilityDecisionsJson(){return uniqueAbilityDecisionsJson;} public void setUniqueAbilityDecisionsJson(String v){uniqueAbilityDecisionsJson=v == null ? "{}" : v;} public boolean isClosed(){return closed;} public void setClosed(boolean v){closed=v;} public String getAttributesJson(){return attributesJson;} public void setAttributesJson(String v){attributesJson=v;} public String getGeneticsJson(){return geneticsJson;} public void setGeneticsJson(String v){geneticsJson=v;} public String getCreationMode(){return creationMode;} public void setCreationMode(String v){creationMode=v;} public String getRace(){return race;} public void setRace(String v){race=v;} public boolean isEinherjer(){return einherjer;} public void setEinherjer(boolean v){einherjer=v;} public boolean isAwakened(){return awakened;} public void setAwakened(boolean v){awakened=v;} public String getSelectedMajorAttributesJson(){return selectedMajorAttributesJson;} public void setSelectedMajorAttributesJson(String v){selectedMajorAttributesJson=v == null ? "[]" : v;} public String getCreationWizardState(){return creationWizardState;} public void setCreationWizardState(String v){creationWizardState=v;} public String getEinherjerOrigin(){return einherjerOrigin;} public void setEinherjerOrigin(String v){einherjerOrigin=v;} public Integer getStartingAge(){return startingAge;} public void setStartingAge(Integer v){startingAge=v;} public Integer getAwakeningAge(){return awakeningAge;} public void setAwakeningAge(Integer v){awakeningAge=v;} public Integer getSheetAge(){return sheetAge;} public void setSheetAge(Integer v){sheetAge=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void touch(){updatedAt=Instant.now();}
}

